"""פרשת נח: ארבע פעולות לפי גילאים (א'-ג', ג'-ה', ו'-ח', ט'-י"ב). שיטת שבעת החלקים, משחקים מוכרים בשמותיהם, פסוקים מנוסח המסורה."""
import json, re, sys, urllib.request
sys.path.insert(0, __file__.rsplit('/', 1)[0])
from content_tools import add_activities, age_label

UA = {'User-Agent': 'Mozilla/5.0 hamadrich-research'}


def flat(x):
    if isinstance(x, str):
        return [x]
    o = []
    for y in x or []:
        o += flat(y)
    return o


def verses(ref):
    url = f'https://www.sefaria.org/api/texts/{ref}?context=0&commentary=0&vhe=Miqra_according_to_the_Masorah'
    d = json.load(urllib.request.urlopen(urllib.request.Request(url, headers=UA), timeout=40))
    t = re.sub('<[^>]+>', '', ' '.join(flat(d['he']))).replace('&thinsp;', ' ').replace('&nbsp;', ' ')
    t = re.sub('[֑-ֽ֯׀]', '', t)
    t = re.sub('י[ְ-ּ]*ה[ְ-ּ]*ו[ְ-ּ]*ה[ְ-ּ]*', 'ה׳', t)
    return re.sub(r'\s+', ' ', t).strip()


def block(ref, title):
    return f'{title}\n{verses(ref)}'


def build(id, title, ages, place, energy, depth, shabbat, equipment, tags, values, subtopics, description, goals, steps, discussion, guide, tip, summary, appendix, shabbat_note=None):
    lo, hi = ages
    flow = []
    for label, body, mins, note in steps:
        s = {'label': f'{label} ({mins} דק׳)', 'body': body}
        if note:
            s['note'] = note
        flow.append(s)
    # הדיון הוא רשימת שאלות: מוסיפים כ-items לשלב הדיון
    for s in flow:
        if s['label'].startswith('דיון'):
            s['items'] = discussion
    total = sum(int(re.search(r'\((\d+) דק', s['label']).group(1)) for s in flow)
    a = {
        'id': id, 'title': title, 'categorySlug': 'activities', 'subtopics': subtopics, 'ageLabel': age_label(lo, hi), 'ageMin': lo, 'ageMax': hi,
        'duration': total, 'groupSize': '8-30 חניכים', 'equipment': equipment, 'shabbat': shabbat, 'place': place, 'energy': energy, 'depth': depth,
        'values': values, 'tags': tags, 'rating': 4.7, 'character': 'D', 'description': description, 'goals': goals,
        'opening': steps[0][1], 'method': '\n\n'.join(s[1] for s in steps[1:-1]), 'discussion': discussion, 'guideNotes': guide, 'summary': summary, 'tip': tip,
        'flow': flow, 'appendices': [appendix],
    }
    if shabbat_note:
        a['shabbatNote'] = shabbat_note
    return a


